// Generated by `kanorio types` — do not edit by hand.

export type DeliveryAssetKind = "image" | "video" | "audio" | "pdf" | "document";

export interface DeliveryAsset {
  assetId: string;
  url: string;
  width: number | null;
  height: number | null;
  /** The asset's default alt text, or the alt written next to the image in rich text and the share image. For an image or gallery field, the item's `imageAlt` wins where set */
  alt: string | null;
  /** Default focal point (0-1 on the original) for object-position or crop gravity; null when unset or centered */
  focus: { x: number; y: number } | null;
  /** url is the watermarked version (or a placeholder while it is being made) */
  watermarked: boolean;
  mimeType: string;
  fileSize: number | null;
  kind: DeliveryAssetKind;
  /** Low-quality image placeholder data URL (16px WebP); null for SVG, animated images and legacy uploads */
  placeholder: string | null;
  edgeColor: string | null;
  processing: "ready" | "processing" | "waiting_storage" | "failed";
  renditions?: { kind: "hls" | "thumbnails"; url: string; mimeType: string; width?: number; height?: number }[];
  streaming?: "partial" | "ready";
  captions?: { locale: string; url: string; mimeType: "text/vtt"; source: "ai" | "upload" | "translation"; edited: boolean }[];
  chapters?: { url: string; mimeType: "text/vtt" };
  /** Credit line set in the media library (photographer or rights holder); filled automatically for stock photos */
  credit: string | null;
  /** Where the file came from (the stock photo's page, the original source) */
  sourceUrl: string | null;
  poster: string | null;
  duration: number | null;
  pageCount: number | null;
  fileName: string | null;
}

export type DeliveryAssetMap = Record<string, DeliveryAsset>;

/**
 * Alt text written for an image where the item uses it, keyed by field id and then asset id:
 * `imageAlt.cover?.[fieldData.cover]`. Use it instead of `assets[id].alt` when present. The same text in every locale.
 */
export type ImageAltMap = Record<string, Record<string, string>>;

export interface ExpandedReference<TFieldData = Record<string, unknown>> {
  id: string;
  slug: string;
  title: string;
  fieldData: TFieldData;
  imageAlt: ImageAltMap;
}

export interface DeliveryItemEnvelope<TFieldData, TExpanded = Record<string, unknown>> {
  id: string;
  /** URL slug in the locale of the response */
  slug: string;
  /**
   * Path of this item's page on the site, in the locale of the response (`/blog/hello`, `/en/blog/hello`).
   * The same address Kanorio lists in the sitemap. Absent when the item has no page of its own:
   * a custom collection without `pathTemplate`, or a category, tag or author whose listing page is off.
   */
  path?: string;
  publishedAt: string | null;
  updatedAt: string;
  fieldData: TFieldData;
  /** Alt text written for an image where this item uses it (image and gallery fields that `fieldData` includes) */
  imageAlt: ImageAltMap;
  expanded?: TExpanded;
  /**
   * Multilingual sites: the locale this item was served in (the requested locale when at least one field has a translation,
   * otherwise the primary locale). Fields fall back one by one: check `fieldLocales` for a particular field
   */
  resolvedLocale?: string;
  /** Multilingual sites: secondary locales that have a published translation of this item */
  availableLocales?: string[];
  /**
   * Multilingual sites: the locale each translatable field was served in, keyed by its path in `fieldData` (`content`,
   * `seo.title`). A field without a translation shows the primary locale. json, image and gallery fields are never machine-translated
   */
  fieldLocales?: Record<string, string>;
  /** Multilingual sites: the slug in every live locale */
  localeSlugs?: Record<string, string>;
  /**
   * Multilingual sites, items that have a page (`path`): the item's path in every live locale, without the locale prefix. Pass it to
   * `seoMetadata`, `buildAlternates` or `languageSwitcher`, which add each locale's prefix; `path` already has the prefix of the response's locale.
   */
  localePaths?: Record<string, string>;
}

export interface DeliveryListResponse<TItem> {
  data: TItem[];
  hasMore: boolean;
  nextCursor: string | null;
  /** Present only when the request asks for it with total=true */
  total?: number;
  assets: DeliveryAssetMap;
}

export interface DeliverySingleResponse<TItem> {
  item: TItem;
  assets: DeliveryAssetMap;
}

export interface DeliveryError {
  error: { code: string; message: string; issues?: unknown };
}

