export type DeliverySiteBrandLogo = { type: "image"; url: string } | { type: "icon"; icon: string };

export interface DeliverySiteBrandColor {
  background: string;
  foreground: string;
}

export interface DeliverySiteBrandFont {
  id: string;
  family: string;
  stylesheetUrl: string | null;
  locales: string[];
}

/** Brand identity from Site settings › Brand: resolved colors, logo, fonts, corner radius and color scheme (same as hosted checkout, sign-in and emails). */
export interface DeliverySiteBrand {
  displayName: string | null;
  logo: { light: DeliverySiteBrandLogo | null; dark: DeliverySiteBrandLogo | null };
  colors: { primary: { light: DeliverySiteBrandColor; dark: DeliverySiteBrandColor } };
  cornerRadius: "soft" | "normal" | "sharp";
  /** system follows the visitor's device; light or dark fixes Kanorio's hosted checkout, sign-in and customer account */
  colorScheme: "system" | "light" | "dark";
  radius: Record<string, string>;
  typography: {
    bodyEnFontId: string;
    bodyZhHantFontId: string;
    bodyZhHansFontId: string;
    bodyJaFontId: string;
    bodyKoFontId: string;
  };
  fonts: DeliverySiteBrandFont[];
}

