/** Blog categories — Categories for blog posts. Managed from the Blog settings page. (blog_categories) */
export interface BlogCategoriesFieldData {
  name: string;
  /** Markdown */
  description?: string | null;
  sort_order?: number | null;
  counts?: { posts: number } | null;
  seo?: { /** SEO title. Filled with the item's own title when the author left it empty; never includes the site name. */ title: string | null; description: string | null; keywords: string[] | null; /** Share image the author chose, as stored: an asset id (look it up in `assets`) or a full URL. For `og:image` use `fieldData.share_image`, which is cropped and has the fallbacks applied. */ ogImage: string | null; ogImageAlt: string | null; ogTitle: string | null; ogDescription: string | null; /** Canonical URL override, when the author set one. */ canonical: string | null; robotsIndex: "index" | "noindex"; robotsFollow: "follow" | "nofollow"; twitterCard: "summary" | "summary_large_image"; /** Title card Kanorio generates from the title (a full URL). `fieldData.share_image` falls back to it. */ autoOgImage: string | null; [key: string]: unknown; } | null;
  /** The image to use as og:image, ready to use: the share image chosen for this page (cropped to 1200x630 the way it was framed), else the title card Kanorio generates. null when there is none. Same image the hosted site uses. source says where the image came from: chosen (the share image the author picked), cover, title_card (generated by Kanorio from the title) or body_image (the first image in the body). When you use share_image as a thumbnail on a list card, skip title_card: the card already shows the title. width and height are the pixel size url delivers, for og:image:width and og:image:height: 1200x630 for a title card or a cropped image, or the largest box of that shape the image holds when the image (or the part the author framed) is smaller; null for an external URL or an SVG. To resize, pass url to imageUrl, srcSet or kanorioImageLoader from @kanorio/sdk: they keep the author's crop. */
  share_image?: { url: string; alt: string | null; source: "chosen" | "cover" | "title_card" | "body_image"; width: number | null; height: number | null } | null;
}

export interface BlogCategoriesExpanded {
}

export type BlogCategoriesItem = DeliveryItemEnvelope<BlogCategoriesFieldData, BlogCategoriesExpanded>;

